using System;using System.Linq;using UnityEngine;using UnityEditor;using UnityEngine.AI;using Codice.Expedition;using Codice.Mechanics;using Codice.Characters;using Codice.UI;
public static class VerifyFourth {
 public static string Layouts(){for(int floor=10;floor<=12;floor++)for(int seed=1;seed<=300;seed++){var l=new ExpeditionLayout(seed,floor);if(!l.Connected()||l.Count>16||l.SecretRoom<0)throw new Exception("Layout "+floor+"/"+seed);for(int r=0;r<l.Count;r++){var p=l.Rooms[r];if(l.RoomAt(new Vector3(p.x*4,l.Height(r),p.y*4))!=r)throw new Exception("Overlapping centre "+floor+"/"+seed+"/"+r);}if(!Resources.Load<GameObject>(ExpeditionFloor.BossResource(seed,floor)))throw new Exception("Missing boss");}return "PASS 900 world-four layouts, unique centres, secrets, bosses";}
 static string Load(int f){EditorApplication.isPaused=false;MainMenuUI.UnlockCheats("jam");ExpeditionFloor.DebugSeed=8137;RunNavigation.StartExpeditionTest(PlayerClass.Warrior,f);return "Loading "+f;}
 public static string Load10()=>Load(10);public static string Load11()=>Load(11);public static string Load12()=>Load(12);
 public static string Paths(){var r=RunDirector.Instance;var f=r.Expedition;r.Player.State.LaboratoryImmortal=true;int valid=0;for(int i=0;i<f.RoomCount;i++){if(i==f.Layout.SecretRoom)continue;NavMeshHit start,end;if(!NavMesh.SamplePosition(f.Center(0),out start,2,-1)||!NavMesh.SamplePosition(f.Center(i),out end,3,-1))throw new Exception("Missing nav floor "+i);var p=new NavMeshPath();if(!NavMesh.CalculatePath(start.position,end.position,-1,p)||p.status!=NavMeshPathStatus.PathComplete)throw new Exception("No route "+i);valid++;}return "PASS floor "+f.FloorNumber+" reachable rooms "+valid;}
 public static string Fight(){var f=RunDirector.Instance.Expedition;JamDebug.Teleport(f.Layout.Boss);return "Entered boss room";}
 public static string Boss(){var f=RunDirector.Instance.Expedition;var b=f.context.arena.ActiveBoss;if(!b||!b.IsAlive||b.GetComponentsInChildren<Renderer>().Length==0)throw new Exception("Boss absent");return "PASS "+b.name+" HP="+b.Health;}
 public static string Merchant(){var f=RunDirector.Instance.Expedition;if(f.Layout.MerchantRoom<0)return "No merchant this seed";JamDebug.Teleport(f.Layout.MerchantRoom);var m=UnityEngine.Object.FindObjectsByType<Merchant>().FirstOrDefault(x=>x.ExpeditionShop);if(!m||!m.visual||!m.visual.GetComponentInChildren<SkinnedMeshRenderer>())throw new Exception("Merchant not connected");return "PASS Nereo skinned model, offers="+m.OfferCount;}
}
